class Attributes
  def initialize(values = {})
    @values =
      if values.is_a?(Hash)
        values.dup
      elsif values.respond_to?(:to_h)
        values.to_h
      else
        {}
      end
  rescue
    @values = {}
  end

  def to_h
    @values.is_a?(Hash) ? @values.dup : {}
  rescue
    {}
  end

  def ==(other)
    other.is_a?(Hash) && @values.is_a?(Hash) && @values == other
  rescue
    false
  end
end
