class EventBroadcaster
  def initialize
    @listeners = []
  end

  def subscribe(listener)
    @listeners << listener
    listener
  end

  def publish(event)
    listeners = @listeners.dup
    listeners.each { |listener| listener.notify(event) }
    listeners.size
  end
end
