class Cache
  def initialize(packer: nil)
    @packer = packer
    @entries = {}
    @stale = {}
  end

  def write(key, payload, stale: false)
    @entries[key] = pack(payload)
    @stale[key] = stale
    self
  end

  def read(key)
    return nil unless @entries.key?(key)
    unpack(@entries[key])
  end

  def sweep
    stale_keys = []

    @entries.each_key do |key|
      # Round-trip the stored entry through the packer (if any) before
      # making the stale decision.
      unpack(@entries[key])
      stale_keys << key if @stale[key]
    end

    stale_keys.each do |key|
      @entries.delete(key)
      @stale.delete(key)
    end

    true
  end

  private

  def pack(payload)
    @packer ? @packer.dump(payload) : payload
  end

  def unpack(stored)
    @packer ? @packer.load(stored) : stored
  end
end
