class SparseArray
  include Enumerable

  def initialize
    @entries = {}
  end

  def [](index)
    @entries[index]
  end

  def []=(index, value)
    @entries[index] = value
  end

  def each
    return enum_for(:each) unless block_given?

    @entries.keys.sort.each do |index|
      yield @entries[index]
    end

    self
  end

  def each_index
    return enum_for(:each_index) unless block_given?

    @entries.keys.sort.each { |index| yield index }

    self
  end

  def size
    @entries.size
  end
  alias length size

  def empty?
    @entries.empty?
  end

  def clear
    @entries.clear
    self
  end

  def delete(index)
    @entries.delete(index)
  end

  def ==(other)
    return false unless other.is_a?(Array) || other.is_a?(SparseArray)

    to_a == other.to_a
  end
end
